// scripts/learn_demo/lib/page.mjs — render the single demo page from sources.
//
// Sources:
//   template.html  structure + placeholders
//   styles.css     inlined into <style>
//   app.js         inlined into <script>
//   content.json   escaped and embedded as <script type="application/json">
//
// index.html and preview/index.html are generated byte-for-byte copies, so the
// raw.githack review link and the local file:// page show the same bytes.

import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { validateContent } from "./contract.mjs";

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");

const TOKENS = ["{{STYLES_CSS}}", "{{APP_JS}}", "{{CONTENT_JSON}}"];
const FORBIDDEN_ABSOLUTE = /https?:\/\//i;

export function readSources(root = ROOT) {
  const read = (name) => readFileSync(join(root, name), "utf8");
  const content = JSON.parse(read("content.json"));
  return {
    template: read("template.html"),
    styles: read("styles.css"),
    app: read("app.js"),
    content,
  };
}

export function renderPage({ template, styles, app, content }) {
  for (const token of TOKENS) {
    if (!template.includes(token)) throw new Error(`template.html is missing ${token}`);
  }
  const json = JSON.stringify(content).replace(/</g, "\\u003c");
  let html = template;
  html = html.replace("{{STYLES_CSS}}", () => styles);
  html = html.replace("{{APP_JS}}", () => app);
  html = html.replace("{{CONTENT_JSON}}", () => json);
  if (!html.endsWith("\n")) html += "\n";
  const stripped = html.replaceAll("http://www.w3.org/2000/svg", "");
  if (FORBIDDEN_ABSOLUTE.test(stripped)) {
    throw new Error("generated page contains an absolute http(s) URL");
  }
  if (/<\/script\s*>/i.test(app)) {
    throw new Error("app.js must not contain a literal closing script tag");
  }
  return html;
}

export function buildDemo({ root = ROOT, write = true } = {}) {
  const sources = readSources(root);
  const validation = validateContent(sources.content);
  if (!validation.ok) {
    return { ok: false, errors: validation.errors, sources };
  }
  const html = renderPage(sources);
  const bytes = Buffer.from(html, "utf8");
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  const index = join(root, "index.html");
  const preview = join(root, "preview", "index.html");
  const previous = existsSync(index) ? readFileSync(index) : null;
  const previousPreview = existsSync(preview) ? readFileSync(preview) : null;
  const drift = !previous || !previous.equals(bytes) || !previousPreview || !previousPreview.equals(bytes);
  if (write) {
    writeFileSync(index, bytes);
    mkdirSync(dirname(preview), { recursive: true });
    writeFileSync(preview, bytes);
  }
  return {
    ok: true,
    errors: [],
    index,
    preview,
    bytes: bytes.length,
    sha256,
    drift,
    identical: write ? readFileSync(preview).equals(readFileSync(index)) : previous && previousPreview
      ? previous.equals(previousPreview)
      : false,
    previousBytes: previous ? previous.length : 0,
  };
}
